181	// normalizeHostedBinding validates the target and strips a quoted /api/v1
182	// suffix. Cell URLs are commonly quoted with that prefix (repo view's apiUrl,
183	// docs examples), but the factsync client appends /api/v1/repos/... itself —
184	// storing the suffix would 404 every sync. OptedOut is false: a fresh binding
185	// is an opt-in.
186	func normalizeHostedBinding(repoID, apiURL string) (brainstore.HostedRepoBinding, error) {
187		if strings.TrimSpace(repoID) == "" {
188			return brainstore.HostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
189		}
190		validated, err := apiurl.Validate(apiURL)
191		if err != nil {
192			return brainstore.HostedRepoBinding{}, err
193		}
194		return brainstore.HostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}, nil
195	}
196	
197	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
198	// there, including an opt-out — running connect is how the user opts back in.
199	func bindHostedRepo(brainDir, repoID, apiURL string) (brainstore.HostedRepoBinding, error) {
200		binding, err := normalizeHostedBinding(repoID, apiURL)
201		if err != nil {
202			return brainstore.HostedRepoBinding{}, err
203		}
204		if err := brainstore.WriteHostedRepoBinding(brainDir, binding); err != nil {
205			return brainstore.HostedRepoBinding{}, err
206		}
207		return binding, nil
208	}
209	
210	// ResolveBinding resolves this repo's CURRENT hosted placement through the
211	// host CLI and normalizes it to a writable binding. The background sync uses
212	// it to detect a deleted-and-reonboarded repo behind a stale binding
213	// (COR-2279); it resolves only — writing a binding stays with connect and the
214	// sync's own guarded rebind.
215	func ResolveBinding(ctx context.Context, runner base.CommandRunner, repoDir string) (brainstore.HostedRepoBinding, error) {
216		placement, err := resolveHostedPlacement(ctx, runner, repoDir)
217		if err != nil {
218			return brainstore.HostedRepoBinding{}, err
219		}
220		return normalizeHostedBinding(placement.RepoID, placement.APIURL)
221	}
222	
223	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
224	// placement.
225	func resolveHostedPlacement(ctx context.Context, runner base.CommandRunner, repoDir string) (hostedPlacement, error) {
226		ctx, cancel := context.WithTimeout(ctx, base.HostedShellOutTimeout)
227		defer cancel()
228		if err := checkHostCLIVersion(ctx, runner, repoDir, minHostCLIVersion); err != nil {
229			return hostedPlacement{}, err
230		}
231		stdout, stderr, err := runner.Run(ctx, repoDir, base.HostEntireBinary, "repo", "view", "--json")
232		if err != nil {
233			return hostedPlacement{}, placementFailureError(err, stderr)
234		}
235		var result hostedPlacement
236		if err := base.DecodeHostCLIJSON(stdout, &result); err != nil {
237			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
238		}
239		return result, nil
240	}
241	
242	// placementFailureError reduces a failed `entire repo view --json` to the line
243	// the host CLI actually said. The runner's wrap carries debug framing — an
244	// argv echo plus the host's "Using context '…'." login banner — that a human
245	// reading connect's failure never needs. Drop the banner, then let
246	// providerdetail.Summary keep the host's Error:-marked or first stderr line.
247	func placementFailureError(runErr error, stderr []byte) error {
248		var kept []string
249		for _, line := range strings.Split(string(stderr), "\n") {
250			line = strings.TrimSpace(line)
251			if line == "" || strings.HasPrefix(line, "Using context ") {
252				continue
253			}
254			kept = append(kept, line)
255		}
256		if summary := providerdetail.Summary(strings.Join(kept, "\n")); summary != "" {
257			return errors.New(summary)
258		}
259		// Nothing usable on stderr: name the command and the cause under the
260		// runner's argv echo (exit status, or a missing host CLI).
261		cause := runErr
262		if unwrapped := errors.Unwrap(runErr); unwrapped != nil {
263			cause = unwrapped
264		}
265		return fmt.Errorf("`entire repo view --json`: %v", cause)
266	}
267	
268	// checkHostCLIVersion refuses placement resolution on a host CLI older than
269	// min, so the failure says "upgrade" instead of repo view's unknown-command
270	// noise. A missing CLI or an unrecognized version line (dev builds) passes:
271	// the repo view call itself is the authority on whether the command exists.
272	func checkHostCLIVersion(ctx context.Context, runner base.CommandRunner, repoDir, min string) error {
273		if min == "" {
274			return nil
275		}
276		stdout, _, err := runner.Run(ctx, repoDir, base.HostEntireBinary, "version")
277		if err != nil {
278			return nil
279		}
280		// First line is "Entire CLI <version>", on some builds with a trailing
281		// "(<commit>)". Take the first field that parses as semver, not a fixed
282		// position, so a build suffix cannot fail-open the gate.
283		line, _, _ := strings.Cut(strings.TrimSpace(string(stdout)), "\n")
284		got := ""
285		for _, field := range strings.Fields(line) {
286			if v := "v" + strings.TrimPrefix(field, "v"); semver.IsValid(v) {
287				got = v
288				break
289			}
290		}
291		if got == "" {
292			return nil
293		}
294		// Compare the release core only: a prerelease or pseudo-version of min
295		// (nightly, git describe) ranks below min in full semver order yet may
296		// already ship repo view — those builds pass and repo view stays the
297		// authority.
298		core := strings.TrimSuffix(got, semver.Build(got))
299		core = strings.TrimSuffix(core, semver.Prerelease(core))
300		if semver.Compare(core, "v"+min) >= 0 {
301			return nil
302		}
303		return fmt.Errorf("entire CLI %s does not support `entire repo view` (needs %s or newer); upgrade the entire CLI and re-run connect", strings.TrimPrefix(got, "v"), min)
304	}
