45	// hostedSyncOutcome reports what one hostedFactsSyncAndPull run did.
46	type hostedSyncOutcome struct {
47		Attempted     bool
48		PullSucceeded bool
49	}
50	
51	// hostedFactsSyncAndPull closes the hosted-memory loop on the per-fact wire
52	// (COR-2126): batch-upsert this machine's store to
53	// brainstore, pull the repo-wide delta feed into the repo-level cache, and
54	// rebuild the store as the pull filter's output plus this machine's
55	// own facts the feed has not seen. No CAS, no branch heads, no proposals —
56	// per-fact storage keeps conflicting facts side by side and resolution stays
57	// deferred to the async pipeline.
58	//
59	// It is a NEVER-FAILS step: every gated or soft failure is one stderr line and
60	// a nil return, because its callers (commit hints, distillation completion, connect)
61	// must not fail on hosted outages. The error return exists for programming
62	// errors only.
63	//
64	// Gate order is fixed: (1) the local-only kill switch always wins; (2) a
65	// recorded opt-out (`entire brain disconnect`) stops sync until `connect`
66	// clears it; (3) the repo binding is the consent AND the connection state —
67	// only `entire brain connect` (or the future onboarding flow) writes it, so an
68	// absent binding means local-only, silently, every run. Background triggers
69	// never connect a repo. (4) a recorded no-access pause (COR-2279) skips the
70	// repo until it expires or connect clears it. (5) apiurl.Validate before any
71	// client exists. A fresh token is minted per call via the host CLI's own login
72	// and held only in memory.
73	//
74	// The outcome reports what actually happened: Attempted is whether the gates
75	// passed and the server was contacted (callers that log success must not
76	// report a gated no-op as a sync that ran); PullSucceeded is whether the pull
77	// half completed — the half that proves the exchange (the per-branch marker
78	// keys off it). Callers that promise a sync to the user (connect) key their
79	// report off PullSucceeded; background callers keep ignoring it.
80	func hostedFactsSyncAndPull(ctx context.Context, errW io.Writer, opts Options, repoDir string, storage repoStorage) (hostedSyncOutcome, error) {
81		if base.BrainNoEgressMode() {
82			return hostedSyncOutcome{}, nil
83		}
84		binding, present, err := brainstore.ReadHostedRepoBinding(storage.BrainDir)
85		if err != nil {
86			// NO unreadable binding may fall through to auto-connect: the file may
87			// hide a recorded opt-out (privacy) or a custom target, and neither
88			// survives a rewrite. Skip loudly; the remedy is an explicit
89			// `entire brain connect`.
90			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
91			return hostedSyncOutcome{}, nil
92		}
93		if !present || binding.OptedOut {
94			return hostedSyncOutcome{}, nil
95		}
96		// A recorded access denial pauses the repo (COR-2279): retrying the same
97		// 403 every trigger only feeds the server's auth-failure monitor. Silent
98		// like the opt-out gate; `entire brain status` reports the pause, and the
99		// line printed when it was recorded named the remedy.
100		if binding.NoAccessUntil.After(opts.Now().UTC()) {
101			return hostedSyncOutcome{}, nil
102		}
103		baseURL, err := apiurl.Validate(binding.BaseURL)
104		if err != nil {
105			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
106			return hostedSyncOutcome{}, nil
107		}
108		token, err := mintHostedToken(ctx, opts.Runner, repoDir, base.HostEntireBinary)
109		if err != nil {
110			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
111			return hostedSyncOutcome{}, nil
112		}
113		srv := &factsync.HTTPServer{BaseURL: baseURL, Token: token, Version: opts.Version}
114	
115		rebound := false
116		for {
117			counts, skipped, pushErr := pushHostedFacts(ctx, storage, srv, binding.RepoID)
118			if skipped > 0 {
119				fmt.Fprintf(errW, "hosted sync: skipped %d unpublishable record(s) whose content id does not re-derive (kept locally, not uploaded)\n", skipped)
120			}
121			pushed := pushErr == nil
122			if pushErr != nil {
123				// A push denial alone still degrades to pull-only: a read-only
124				// grant is a real state (push 403, pull 200 — the COR-2030 staging
125				// smoke hit exactly this) and the team's memories must keep
126				// landing through it.
127				fmt.Fprintf(errW, "hosted sync: publish failed (local brain unaffected): %v; pull-only\n", pushErr)
128			}
129			kept, total, manifestErr, pullErr := pullHostedFacts(ctx, opts, repoDir, storage, srv, binding.RepoID, baseURL, token)
130			if errors.Is(pullErr, factsync.ErrNoAccess) {
131				// The pull is the half every caller is granted on a healthy
132				// binding, so its denial means the binding itself is stale: the
133				// repo was deleted or this caller lost access (brainstore
134				// deliberately serves both as 403). Retrying cannot help —
135				// re-resolve placement once, and pause the repo when that does
136				// not produce a different repo to talk to.
137				if !rebound {
138					if fresh, ok := rebindStaleHostedRepo(ctx, errW, opts, repoDir, storage.BrainDir, binding); ok {
139						binding = fresh
140						rebound = true
141						continue
142					}
143				}
144				pauseHostedSyncNoAccessContext(ctx, errW, opts, storage.BrainDir, binding)
145				return hostedSyncOutcome{Attempted: true}, nil
146			}
147			if pullErr != nil {
148				fmt.Fprintf(errW, "hosted sync: pull failed (local brain unaffected): %v\n", pullErr)
149				return hostedSyncOutcome{Attempted: true}, nil
150			}
151			if pushed {
152				// The marker records that this repo completed a sync against this
153				// target; the blind-spot note keys off its absence. It needs BOTH
154				// halves: a pull-only run leaves it unwritten, and so does a failed
155				// pull — the empty-store push "succeeds" without contacting the
156				// server, so the pull is what proves the exchange happened.
157				if err := writeHostedFactsBindingContext(ctx, storage.BrainDir, binding.RepoID, baseURL); err != nil {
158					fmt.Fprintf(errW, "hosted sync: record hosted target: %v\n", err)
159				}
160			}
161			if manifestErr != nil {
162				fmt.Fprintf(errW, "hosted sync: facts updated, but the source manifest could not be refreshed: %v\n", manifestErr)
163			}
164			if !binding.NoAccessUntil.IsZero() {
165				// This run started past an expired pause and the pull succeeded:
166				// access is back, so retire the pause instead of leaving status
167				// reporting it forever. Guarded like the pause write — a binding
168				// another writer replaced meanwhile is not touched.
169				if err := clearHostedSyncNoAccessContext(ctx, storage.BrainDir, binding); err != nil {
170					fmt.Fprintf(errW, "hosted sync: clear expired no-access pause: %v\n", err)
171				}
172			}
173			fmt.Fprintf(errW, "hosted sync: pushed added=%d changed=%d unchanged=%d; feed facts=%d kept=%d\n",
174				counts.Added, counts.Changed, counts.Unchanged, total, kept)
175			return hostedSyncOutcome{Attempted: true, PullSucceeded: true}, nil
176		}
177	}
178	
179	// rebindStaleHostedRepo handles the deleted-and-reonboarded case behind a
180	// pull denial: if the origin now resolves to a DIFFERENT repo id in the SAME
181	// cell, the old binding points at a dead repo and the consent it records
182	// carries over to its replacement. The cell must match so an explicit
183	// non-default binding (--repo-id/--api-url to another cell or staging) is
184	// never silently retargeted to the resolved placement. The write re-checks
185	// the binding under the lock: a concurrent disconnect or connect wins.
186	func rebindStaleHostedRepo(ctx context.Context, errW io.Writer, opts Options, repoDir, brainDir string, stale brainstore.HostedRepoBinding) (brainstore.HostedRepoBinding, bool) {
187		fresh, err := connect.ResolveBinding(ctx, opts.Runner, repoDir)
188		if err != nil || fresh.RepoID == "" || fresh.RepoID == stale.RepoID || fresh.BaseURL != stale.BaseURL {
189			return brainstore.HostedRepoBinding{}, false
190		}
191		written := false
192		err = brainstore.MutateHostedRepoBindingContext(ctx, brainDir, func(current brainstore.HostedRepoBinding) (brainstore.HostedRepoBinding, bool) {
193			if current.OptedOut || current.RepoID != stale.RepoID || current.BaseURL != stale.BaseURL {
194				return current, false
195			}
196			written = true
197			return fresh, true
198		})
199		if err != nil || !written {
200			return brainstore.HostedRepoBinding{}, false
201		}
202		fmt.Fprintf(errW, "hosted sync: repo was re-onboarded on Entire; rebound %s -> %s\n", stale.RepoID, fresh.RepoID)
203		return fresh, true
204	}
