221	// pauseHostedSyncNoAccess records the no-access pause next to the binding and
222	// says so once. The write re-checks the binding under the lock so a
223	// concurrent connect or disconnect is never stamped with a stale denial. The
224	// "paused" line prints only when the pause was actually recorded: a declined
225	// write means another writer owns the binding now (its state speaks for
226	// itself), and a failed write means the next trigger will try again.
227	func pauseHostedSyncNoAccess(errW io.Writer, opts Options, brainDir string, stale brainstore.HostedRepoBinding) {
228		pauseHostedSyncNoAccessContext(context.Background(), errW, opts, brainDir, stale)
229	}
230	
231	func pauseHostedSyncNoAccessContext(ctx context.Context, errW io.Writer, opts Options, brainDir string, stale brainstore.HostedRepoBinding) {
232		until := opts.Now().UTC().Add(hostedNoAccessBackoff)
233		written := false
234		err := brainstore.MutateHostedRepoBindingContext(ctx, brainDir, func(current brainstore.HostedRepoBinding) (brainstore.HostedRepoBinding, bool) {
235			if current.OptedOut || current.RepoID != stale.RepoID || current.BaseURL != stale.BaseURL {
236				return current, false
237			}
238			current.NoAccessUntil = until
239			written = true
240			return current, true
241		})
242		if err != nil {
243			fmt.Fprintf(errW, "hosted sync: no access to repo %s on Entire, but recording the pause failed: %v\n", stale.RepoID, err)
244			return
245		}
246		if !written {
247			return
248		}
249		fmt.Fprintf(errW, "hosted sync: no access to repo %s on Entire (deleted, or this account lost access); sync paused until %s — run '%s' once access is granted\n",
250			stale.RepoID, until.Format(time.RFC3339), base.BrainInvocation(os.LookupEnv, "connect"))
251	}
252	
253	// pushHostedFacts batch-upserts the branch store. Idempotent server-side, so
254	// every trigger can fire it without coordination. It returns the upsert counts
255	// and how many unverifiable records stayed home; a non-nil error means the
256	// publish did not complete and the branch must not be marked as synced. The
257	// caller owns presentation: background sync degrades to pull-only with one
258	// stderr line, manual sync fails the command (COR-2202 honesty).
259	func pushHostedFacts(ctx context.Context, storage repoStorage, srv *factsync.HTTPServer, repoID string) (factsync.UpsertCounts, int, error) {
260		lock, err := acquireHostedUploadLock(ctx, storage.BrainDir)
261		if err != nil {
262			return factsync.UpsertCounts{}, 0, err
263		}
264		defer lock.Close()
265		receiptPath := hostedUploadReceiptPath(srv.BaseURL, repoID)
266		receipts, err := loadHostedUploadReceipts(storage.BrainDir, receiptPath)
267		if err != nil {
268			return factsync.UpsertCounts{}, 0, err
269		}
270	
271		facts, err := factstore.Load(storage.BrainDir)
272		if err != nil {
273			return factsync.UpsertCounts{}, 0, err
274		}
275		if len(facts) == 0 {
276			// Nothing to publish counts as a successful (empty) publish; the
277			// server rejects an empty body, so don't send one.
278			return factsync.UpsertCounts{}, 0, nil
279		}
280		// Redact local-only provenance coordinates before these facts leave, and
281		// verify this member's own facts BEFORE publishing them — the server
282		// rejects a whole batch for one malformed record, so the check runs here,
283		// per record: one corrupted line must not hold the rest of the store
284		// hostage. Unverifiable records stay home with a note; everything else
285		// uploads.
286		egress := factsync.SanitizeForEgress(facts)
287		publishable := egress[:0]
288		skipped := 0
289		for _, rec := range egress {
290			if err := factmerge.VerifyIdentity(rec); err != nil {
291				skipped++
292				continue
293			}
294			publishable = append(publishable, rec)
295		}
296		egress = publishable
297		if len(egress) == 0 {
298			// Everything was unpublishable: nothing was shared, so this is a
299			// failed publish, not a vacuous success.
300			return factsync.UpsertCounts{}, skipped, errors.New("no publishable records")
301		}
302		var total factsync.UpsertCounts
303		pending := egress[:0]
304		versions := map[string]bool{}
305		for _, rec := range egress {
306			body, err := json.Marshal(rec)
307			if err != nil {
308				return total, skipped, err
309			}
310			version := hostedUploadHash(body)
311			if receipts.Versions[version] || versions[version] {
312				total.Unchanged++
313				continue
314			}
315			versions[version] = true
316			pending = append(pending, rec)
317		}
318		egress = pending
319		for start := 0; start < len(egress); start += hostedUpsertChunk {
320			end := min(start+hostedUpsertChunk, len(egress))
321			var buf bytes.Buffer
322			if err := factmerge.WriteNDJSON(&buf, egress[start:end]); err != nil {
323				return total, skipped, err
324			}
325			counts, err := srv.UpsertFacts(ctx, repoID, buf.Bytes())
326			if err != nil {
327				return total, skipped, err
328			}
329			total.Added += counts.Added
330			total.Changed += counts.Changed
331			total.Unchanged += counts.Unchanged
332			// Acknowledge only the snapshot actually sent, not a concurrent writer's
333			// newer version. Persist each successful chunk before sending the next.
334			for _, rec := range egress[start:end] {
335				body, err := json.Marshal(rec)
336				if err != nil {
337					return total, skipped, err
338				}
339				receipts.Versions[hostedUploadHash(body)] = true
340			}
341			if err := saveHostedUploadReceipts(storage.BrainDir, receiptPath, receipts); err != nil {
342				return total, skipped, err
343			}
344		}
345		return total, skipped, nil
346	}
347	
348	var errHostedFeedChanged = errors.New("hosted feed changed during preparation")
349	
350	// pullHostedFacts fetches the repo delta feed since the stored cursor into
351	// the repo-level cache, filters the WHOLE cache by local visibility
352	// (keepHostedFact), and rebuilds the branch store from the result. Returns
353	// (kept, total cached) for the caller's summary line.
354	//
355	// Fetch and filter without the writer lock. Revalidate the cache at commit
356	// and merge into the latest local store, preserving concurrent user writes.
357	func pullHostedFacts(ctx context.Context, opts Options, repoDir string, storage repoStorage, srv *factsync.HTTPServer, repoID, baseURL, token string) (kept, total int, manifestErr, err error) {
358		for attempt := 1; ; attempt++ {
359			if err := ctx.Err(); err != nil {
360				return 0, 0, nil, err
361			}
362			kept, total, manifestErr, err = pullHostedFactsAttempt(ctx, opts, repoDir, storage, srv, repoID, baseURL, token)
363			if !errors.Is(err, errHostedFeedChanged) {
364				return
365			}
366			if attempt >= maxHostedFeedAttempts {
367				return 0, 0, nil, fmt.Errorf("hosted feed changed during %d pull attempts; retry sync: %w", attempt, err)
368			}
369			timer := time.NewTimer(hostedFeedRetryDelay)
370			select {
371			case <-ctx.Done():
372				timer.Stop()
373				return 0, 0, nil, ctx.Err()
374			case <-timer.C:
375			}
376		}
377	}
378	
379	func pullHostedFactsAttempt(ctx context.Context, opts Options, repoDir string, storage repoStorage, srv *factsync.HTTPServer, repoID, baseURL, token string) (kept, total int, manifestErr, err error) {
380		feedDir, err := hostedFeedDirForKey(opts.Env, storage.Key)
381		if err != nil {
382			return 0, 0, nil, err
383		}
384		err = func() error {
385			var state hostedFeedState
386			var items map[string]factsync.FeedItem
387			var binding brainstore.HostedRepoBinding
388			var bound bool
389			// Snapshot under the existing lock so released clients cannot expose
390			// half of a cache replacement. Network and Git work follow unlocked.
391			if err := brainstore.WithBrainWriteLockContext(ctx, storage.BrainDir, func() error {
392				var loadErr error
393				state, items, loadErr = loadHostedFeedCache(feedDir)
394				if loadErr != nil {
395					return loadErr
396				}
397				binding, bound, loadErr = brainstore.ReadHostedRepoBinding(storage.BrainDir)
398				return loadErr
399			}); err != nil {
400				return err
401			}
402			snapshot, err := json.Marshal(struct {
403				State hostedFeedState
404				Items map[string]factsync.FeedItem
405			}{state, items})
406			if err != nil {
407				return err
408			}
409			// A different hosted target invalidates everything: cached facts from
410			// another repo (or another cell) must never rebuild this branch store.
411			if state.RepoID != repoID || state.BaseURL != baseURL {
412				state = hostedFeedState{RepoID: repoID, BaseURL: baseURL}
413				items = make(map[string]factsync.FeedItem)
414			}
415			cursor := state.Cursor
416			cursorReset := false
417			for page := 0; page < maxHostedFeedPages; page++ {
418				feedPage, err := srv.FactsFeedPage(ctx, repoID, cursor, hostedFeedPageSize)
419				if errors.Is(err, factsync.ErrInvalidPageToken) && !cursorReset && cursor != "" {
420					// The server's cursor epoch moved: the stored position is
421					// meaningless, so refetch from the start. The cache rebuild is
422					// idempotent (keyed by fact id).
423					cursorReset = true
424					cursor = ""
425					items = make(map[string]factsync.FeedItem)
426					continue
427				}
428				if err != nil {
429					return err
430				}
431				if len(feedPage.Items) == 0 {
432					break
433				}
434				for _, item := range feedPage.Items {
435					if item.Record.ID != "" {
436						items[item.Record.ID] = item
437					}
438				}
439				if feedPage.NextPageToken == nil {
440					break
441				}
442				cursor = *feedPage.NextPageToken
443			}
444	
445			member := jwtSubClaim(token)
446			reachable := newCommitReachability(ctx, opts.Runner, repoDir)
447			var keptRecords []factRecord
448			var retirements []factRecord
449			for _, item := range items {
450				rec := item.Record
451				// Server attribution is the only author source: it overwrites
452				// whatever the wire record carried (an old or hostile peer's value
453				// must not survive).
454				rec.Author = item.CreatedByHandle
455				if keepHostedFact(item, member, reachable) {
456					keptRecords = append(keptRecords, rec)
457					continue
458				}
459				// A retirement bypasses the keep filter: the filter judges
460				// reachability from the CURRENT branch head, but a lifecycle
461				// transition for a record this store already holds must apply
462				// wherever the retiring commit lives — otherwise recall keeps
463				// serving a statement the team retracted. Applied below to
464				// existing ids only; an unreachable retirement never adopts the
465				// record it retires.
466				if rec.Status != factStatusActive {
467					retirements = append(retirements, rec)
468				}
469			}
470			// Same fail-closed rule as the old head pull: a record whose content id
471			// does not re-derive is a forgery, and nothing from this feed — cache
472			// and cursor included — may land until the server stops serving it.
473			// Retirements are held to the same proof: an unverifiable id must not
474			// retire anything.
475			if err := factmerge.VerifyIdentities(append(append([]factRecord{}, keptRecords...), retirements...)); err != nil {
476				return fmt.Errorf("refused untrustworthy feed: %w", err)
477			}
478			sort.Slice(keptRecords, func(i, j int) bool { return keptRecords[i].ID < keptRecords[j].ID })
479	
480			return brainstore.WithBrainWriteLockContext(ctx, storage.BrainDir, func() error {
481				currentBinding, currentBound, err := brainstore.ReadHostedRepoBinding(storage.BrainDir)
482				if err != nil {
483					return err
484				}
485				if currentBound != bound || currentBinding != binding {
486					return fmt.Errorf("hosted connection changed during pull; retry with the current connection")
487				}
488				currentState, currentItems, err := loadHostedFeedCache(feedDir)
489				if err != nil {
490					return err
491				}
492				current, err := json.Marshal(struct {
493					State hostedFeedState
494					Items map[string]factsync.FeedItem
495				}{currentState, currentItems})
496				if err != nil {
497					return err
498				}
499				if !bytes.Equal(snapshot, current) {
500					return errHostedFeedChanged
501				}
502				if err := writeHostedFeedCache(feedDir, hostedFeedState{RepoID: repoID, BaseURL: baseURL, Cursor: cursor}, items); err != nil {
503					return err
504				}
505	
506				existing, err := factstore.Load(storage.BrainDir)
507				if err != nil {
508					return err
509				}
510				for _, fact := range keptRecords {
511					// upsertFact never moves a local status, so a locally retracted
512					// fact stays retracted whatever the feed says. The feed is
513					// authoritative for RETIREMENTS, though: lifecycle moves one way —
514					// active to retired, never a revival.
515					existing = upsertFact(existing, fact)
516					if fact.Status == factStatusActive {
517						continue
518					}
519					if i := indexOfFact(existing, fact.ID); i >= 0 && existing[i].Status == factStatusActive {
520						existing[i].Status = fact.Status
521						existing[i].SupersededBy = fact.SupersededBy
522						existing[i].UpdatedAt = opts.Now().UTC()
523					}
524				}
525				// Retirements the keep filter rejected still apply to records already
526				// stored — same one-way move, never an adoption.
527				for _, fact := range retirements {
528					if i := indexOfFact(existing, fact.ID); i >= 0 && existing[i].Status == factStatusActive {
529						existing[i].Status = fact.Status
530						existing[i].SupersededBy = fact.SupersededBy
531						existing[i].UpdatedAt = opts.Now().UTC()
532					}
533				}
534				// Pull never evicts a stored record. The keep filter judges
535				// reachability from the CURRENT branch head, and the flat store holds
536				// every branch's pulls — a teammate fact pulled on another branch must
537				// stay recallable when syncing here. A stored fact leaves the store
538				// when the feed retires it (the lifecycle moves above, which apply
539				// regardless of the keep filter) or when the checkpoint mirror sweep
540				// drops provenance the whole repository no longer has; the keep filter
541				// gates ADOPTION only.
542				if err := factstore.Write(storage.BrainDir, existing); err != nil {
543					return err
544				}
545				// A manifest failure reports alongside the successful pull instead of
546				// masking it.
547				manifestErr = updateFactSourceManifestRecordsLocked(storage.BrainDir, opts.Now().UTC(), existing)
548				kept, total = len(keptRecords), len(items)
549				return nil
550			})
551		}()
552		return kept, total, manifestErr, err
553	}
