23	const (
24		// hostedUpsertChunk stays well under brainstore's 5000-record batch cap
25		// and its 32 MiB body cap.
26		hostedUpsertChunk = 1000
27		// hostedFeedPageSize is brainstore's page-size ceiling.
28		hostedFeedPageSize = 100
29		// maxHostedFeedPages bounds one pull so the never-fails path cannot spin
30		// on a pathological feed. ponytail: a delta larger than 20k records
31		// finishes on the next trigger — the cursor persists either way.
32		maxHostedFeedPages = 200
33		// Concurrent syncs can invalidate a prepared pull. Bound repeated network
34		// and Git work; a later trigger can resume from the latest durable cursor.
35		maxHostedFeedAttempts = 3
36		hostedFeedRetryDelay  = 100 * time.Millisecond
37		// hostedNoAccessBackoff is how long every background trigger skips a repo
38		// after the server denied access to the binding (COR-2279). Long enough to
39		// stop a stuck client from tripping the server's auth-failure monitor,
40		// short enough that a restored grant resumes on its own; `entire brain
41		// connect` resumes immediately.
42		hostedNoAccessBackoff = 24 * time.Hour
43	)
