179	// rebindStaleHostedRepo handles the deleted-and-reonboarded case behind a
180	// pull denial: if the origin now resolves to a DIFFERENT repo id in the SAME
181	// cell, the old binding points at a dead repo and the consent it records
182	// carries over to its replacement. The cell must match so an explicit
183	// non-default binding (--repo-id/--api-url to another cell or staging) is
184	// never silently retargeted to the resolved placement. The write re-checks
185	// the binding under the lock: a concurrent disconnect or connect wins.
186	func rebindStaleHostedRepo(ctx context.Context, errW io.Writer, opts Options, repoDir, brainDir string, stale brainstore.HostedRepoBinding) (brainstore.HostedRepoBinding, bool) {
187		fresh, err := connect.ResolveBinding(ctx, opts.Runner, repoDir)
188		if err != nil || fresh.RepoID == "" || fresh.RepoID == stale.RepoID || fresh.BaseURL != stale.BaseURL {
189			return brainstore.HostedRepoBinding{}, false
190		}
191		written := false
192		err = brainstore.MutateHostedRepoBindingContext(ctx, brainDir, func(current brainstore.HostedRepoBinding) (brainstore.HostedRepoBinding, bool) {
193			if current.OptedOut || current.RepoID != stale.RepoID || current.BaseURL != stale.BaseURL {
194				return current, false
195			}
196			written = true
197			return fresh, true
198		})
199		if err != nil || !written {
200			return brainstore.HostedRepoBinding{}, false
201		}
202		fmt.Fprintf(errW, "hosted sync: repo was re-onboarded on Entire; rebound %s -> %s\n", stale.RepoID, fresh.RepoID)
203		return fresh, true
204	}
