12	// newCommitReachability answers "is this commit an ancestor of HEAD?" with
13	// one memoized `git merge-base --is-ancestor` per distinct commit. Any
14	// failure — including a commit this clone has never seen (squash merge, gc,
15	// shallow clone) — is quietly "unreachable": absence of history is a normal
16	// state here, not an error worth a line per fact.
17	func newCommitReachability(ctx context.Context, runner CommandRunner, repoDir string) func(commit string) bool {
18		memo := make(map[string]bool)
19		return func(commit string) bool {
20			if commit == "" {
21				return false
22			}
23			if known, ok := memo[commit]; ok {
24				return known
25			}
26			_, _, err := runner.Run(ctx, repoDir, "git", "merge-base", "--is-ancestor", commit, "HEAD")
27			memo[commit] = err == nil
28			return memo[commit]
29		}
30	}
31	
32	// keepHostedFact is the local pull filter from the COR-2110 v3 design: the
33	// server ships the whole repo feed and the client keeps what its own git
34	// graph and identity justify. First match wins:
35	//
36	//  1. A merged trail id — stamped by brainstore only at trail merge — marks
37	//     the fact main-visible even when its anchor commits never became
38	//     ancestors (squash merges rewrite them).
39	//  2. The member's own facts follow them to every machine. Checked before
40	//     reachability: it is free, while the anchor loop shells out to git.
41	//     A member's own commit-anchored facts must not each cost a git call.
42	//  3. Any anchor commit reachable from HEAD.
43	//  4. No session/commit anchors at all: the repo pool, kept by everyone.
44	//
45	// ponytail: rule 2 keys on the fact's server-stamped creator, not per-anchor
46	// session ownership — a teammate-created fact that unions in one of this
47	// member's session anchors is dropped until its commits merge. Upgrade path:
48	// match anchor session ids against the local session manifest as well.
49	func keepHostedFact(item factsync.FeedItem, memberAccountID string, reachable func(string) bool) bool {
50		if item.TrailID != "" {
51			return true
52		}
53		if memberAccountID != "" && item.CreatedBy == memberAccountID {
54			return true
55		}
56		anchored := false
57		for _, anchor := range item.Record.Provenance {
58			if anchor.Commit != "" && reachable(anchor.Commit) {
59				return true
60			}
61			if anchor.Commit != "" || anchor.SessionID != "" {
62				anchored = true
63			}
64		}
65		return !anchored
66	}
67	
68	// hasLocalProvenance reports whether a record carries an anchor only this
69	// machine's distill could have written: the brain-relative transcript path,
70	// which SanitizeForEgress strips before any record leaves.
71	func hasLocalProvenance(rec factRecord) bool {
72		for _, anchor := range rec.Provenance {
73			if anchor.Transcript != "" {
74				return true
75			}
76		}
77		return false
78	}
79	
80	// jwtSubClaim extracts the sub claim from a JWT without verifying it. The
81	// token comes from our own host CLI's login and the claim is used only to
82	// recognize this member's facts in the pull filter — never as an authz
83	// input. Any malformed input is "", which simply disables the member rule.
84	func jwtSubClaim(token string) string {
85		parts := strings.Split(token, ".")
86		if len(parts) != 3 {
87			return ""
88		}
89		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
90		if err != nil {
91			return ""
92		}
93		var claims struct {
94			Sub string `json:"sub"`
95		}
96		if err := json.Unmarshal(payload, &claims); err != nil {
97			return ""
98		}
99		return claims.Sub
100	}
